#include <bits/stdc++.h>
using namespace std;

class Test {
public:
    int readInt() {
        int val = 0;
        bool negativeFlag = false;
        int ch;
        try {
            bool startedReading = false;
            while ((ch = getchar()) != EOF) {
                if (ch == '-') {
                    startedReading = true;
                    negativeFlag = true;
                    continue;
                } else if (ch >= '0' && ch <= '9') {
                    startedReading = true;
                    val = val * 10 + (ch - '0');
                } else if (startedReading) {
                    break;
                }
            }
        } catch (...) {
        }
        return negativeFlag ? -val : val;
    }

    int R, C;
    vector<vector<long long>> comb;
    long long minDist;
    vector<int> countA, countB;
    map<long long, long long> memoMap;
    string seqChars;

    void search(long long x, long long y, int v1, int v2) {
        long long diff = llabs(x - y);
        if (minDist <= 1 || diff - comb[v1][R] * comb[v2][R] >= minDist) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < minDist) minDist = diff;
            return;
        }
        if (v1 >= R) {
            long long deltaX = comb[v1][R] - comb[v1 - 1][R], deltaY = comb[v2][R];
            search(x, y + deltaX * deltaY, v1 - 1, v2);
        }
        if (v2 >= R) {
            long long deltaX = comb[v1][R], deltaY = comb[v2][R] - comb[v2 - 1][R];
            search(x + deltaX * deltaY, y, v1, v2 - 1);
        }
    }

    long long recurse(long long x, long long y, int v1, int v2) {
        long long key = x * 10000LL + v1 * 100 + v2;
        auto cachedValIt = memoMap.find(key);
        if (cachedValIt != memoMap.end()) return cachedValIt->second;
        long long res = 0LL;
        long long d = llabs(x - y);
        if (d - comb[v1][R] * comb[v2][R] > minDist) {
            memoMap[key] = res;
            return res;
        }
        if (v1 < R || v2 < R) {
            int sumIdx = v1 + v2;
            if (v1 >= countA[sumIdx] && v2 >= countB[sumIdx]) {
                v1 -= countA[sumIdx];
                v2 -= countB[sumIdx];
                res = comb[v1 + v2][v1];
                memoMap[key] = res;
                return res;
            }
            memoMap[key] = res;
            return res;
        }
        char c = seqChars[v1 + v2 - 1];
        if (c != 'B') {
            long long c1 = comb[v1][R] - comb[v1 - 1][R], s2 = comb[v2][R];
            res += recurse(x, y + c1 * s2, v1 - 1, v2);
        }
        if (c != 'A') {
            long long s1 = comb[v1][R], c2 = comb[v2][R] - comb[v2 - 1][R];
            res += recurse(x + s1 * c2, y, v1, v2 - 1);
        }
        memoMap[key] = res;
        return res;
    }

    void process() {
        R = readInt(); C = readInt(); getchar();
        getline(cin, seqChars);
        int sizeSeq = (int)seqChars.size();
        int maxSize = 2 * (R + C);
        comb.assign(maxSize + 1, vector<long long>(maxSize + 1, 0));
        for (int i = 0; i <= maxSize; i++) {
            for (int j = 0; j <= maxSize; j++) {
                if (j == 0) comb[i][j] = 1;
                else if (i == 0) comb[i][j] = 0;
                else comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            }
        }
        countA.assign(maxSize + 1, 0);
        countB.assign(maxSize + 1, 0);
        int v1 = R + C, v2 = R + C;
        long long xCoord = 0, yCoord = 0;
        while (v1 >= R && v2 >= R) {
            if (xCoord > yCoord) {
                long long c1 = comb[v1][R] - comb[v1 - 1][R], s2 = comb[v2][R];
                yCoord += c1 * s2;
                v1--;
            } else {
                long long s1 = comb[v1][R], c2 = comb[v2][R] - comb[v2 - 1][R];
                xCoord += s1 * c2;
                v2--;
            }
        }
        minDist = llabs(xCoord - yCoord);
        search(0, 0, R + C, R + C);
        for (int i = 0; i < sizeSeq; i++) {
            countA[i + 1] = countA[i] + (seqChars[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (seqChars[i] == 'B' ? 1 : 0);
        }
        long long ans = recurse(0, 0, R + C, R + C);
        cout << ans << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    Test t;
    t.process();
    return 0;
}

